function setup() {
    //Creating canvas the size of 600x600
    createCanvas(600, 600);
    background('#C6B4E8')

}

function draw() {
    textSize(30);
    textAlign(CENTER, CENTER);
    fill('#F2F2F2');
    stroke('#6140a1');
    strokeWeight(1.5);
    text('What prize fantastic prize will you get?', 300, 100);
}